entries[43629] = { ["name"] = "Uther Lightbringer's Gold Coin", ["text"] = "Binds when picked up\nUse: Throw this coin back into the Dalaran fountain.\n\"Young Arthas must learn patience to temper his power. I will pray that he one day learns how to lead with care rather than force.\"\nSell Price: 1 25" }
